sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // implement resource here
    try {

        var requestData = request.body.data;
        var a = requestData.publisher;
		gs.log("A in Api" + JSON.stringify(a));
		var name = requestData.filterName;
        // var name = 'Top ten publishers for SAM workspace';
        var filter = new GlideRecord('sys_filter');
        filter.addQuery('title=' + name);
        filter.query();

        if (filter.next()) {
            filter.filter = "norm_publisher.nameIN" + a + "^EQ";
            filter.update();
        } else {
            filter.title = name;
            filter.table = "cmdb_sam_sw_discovery_model";
            filter.filter = "norm_publisher.nameIN" + a + "^EQ";
            filter.insert();
        }
		response.setStatus(200);
        response.setBody({
            status: 'success',
            data: "result"
        });
    } catch (e) {
        response.setStatus(500);
        response.setBody({
            status: 'error',
            message: e.message
        });
    }

})(request, response);
